=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO completer with edge/level interrupt detection.
// Implements microarchitecture.md against interface_spec.md.
module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer N          = 8
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output reg  [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  // Bits 0..N-1 set: the pins that exist.
  localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'h1 << N) - 32'h1);

  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // ---------------------------------------------------------------- decode
  wire        access     = psel & penable;
  wire [3:0]  idx        = paddr[5:2];
  wire        upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire        mapped     = (paddr[1:0] == 2'b00) && upper_zero && (idx <= IDX_INTR_STATUS);
  wire        wr_en      = access & pwrite & mapped;
  wire        rd_en      = access & ~pwrite & mapped;
  wire [31:0] wmask      = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

  // --------------------------------------------------------- input widening
  wire [31:0] in_w;
  genvar g;
  generate
    for (g = 0; g < 32; g = g + 1) begin : g_in
      if (g < N) begin : g_pin
        assign in_w[g] = gpio_in[g];
      end else begin : g_nopin
        assign in_w[g] = 1'b0;
      end
    end
  endgenerate

  // -------------------------------------------------------------- registers
  reg [31:0] data_out_q, dir_q, in_q, in_prev_q;
  reg [31:0] rise_en_q, fall_en_q, high_en_q, low_en_q, irq_en_q, status_q;

  reg [31:0] data_out_d, dir_d;
  reg [31:0] rise_en_d, fall_en_d, high_en_d, low_en_d, irq_en_d;
  reg [31:0] clear;

  always @* begin
    data_out_d = data_out_q;
    dir_d      = dir_q;
    rise_en_d  = rise_en_q;
    fall_en_d  = fall_en_q;
    high_en_d  = high_en_q;
    low_en_d   = low_en_q;
    irq_en_d   = irq_en_q;
    clear      = 32'h0;
    if (wr_en) begin
      case (idx)
        IDX_DATA_OUT:    data_out_d = (data_out_q & ~wmask) | (pwdata & wmask);
        IDX_DIR:         dir_d      = (dir_q      & ~wmask) | (pwdata & wmask);
        IDX_INTR_RISE:   rise_en_d  = (rise_en_q  & ~wmask) | (pwdata & wmask);
        IDX_INTR_FALL:   fall_en_d  = (fall_en_q  & ~wmask) | (pwdata & wmask);
        IDX_INTR_HIGH:   high_en_d  = (high_en_q  & ~wmask) | (pwdata & wmask);
        IDX_INTR_LOW:    low_en_d   = (low_en_q   & ~wmask) | (pwdata & wmask);
        IDX_INTR_ENABLE: irq_en_d   = (irq_en_q   & ~wmask) | (pwdata & wmask);
        IDX_INTR_STATUS: clear      = pwdata & wmask;
        default:         clear      = 32'h0; // DATA_IN is read only
      endcase
    end
  end

  // Detection uses the enables as they are before the edge.
  wire [31:0] detected = (((in_q & ~in_prev_q) & rise_en_q)
                        | ((~in_q & in_prev_q) & fall_en_q)
                        | (in_q & high_en_q)
                        | (~in_q & low_en_q)) & PINS;
  // Detection is ORed last: it beats a clear on the same edge.
  wire [31:0] status_d = (status_q & ~clear) | detected;

  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'h0;
      dir_q      <= 32'h0;
      in_q       <= 32'h0;
      in_prev_q  <= 32'h0;
      rise_en_q  <= 32'h0;
      fall_en_q  <= 32'h0;
      high_en_q  <= 32'h0;
      low_en_q   <= 32'h0;
      irq_en_q   <= 32'h0;
      status_q   <= 32'h0;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      in_q       <= in_w;
      in_prev_q  <= in_q;
      rise_en_q  <= rise_en_d;
      fall_en_q  <= fall_en_d;
      high_en_q  <= high_en_d;
      low_en_q   <= low_en_d;
      irq_en_q   <= irq_en_d;
      status_q   <= status_d;
    end
  end

  // ------------------------------------------------------------- read path
  always @* begin
    prdata = 32'h0;
    if (rd_en) begin
      case (idx)
        IDX_DATA_OUT:    prdata = data_out_q;
        IDX_DIR:         prdata = dir_q;
        IDX_DATA_IN:     prdata = in_q;
        IDX_INTR_RISE:   prdata = rise_en_q;
        IDX_INTR_FALL:   prdata = fall_en_q;
        IDX_INTR_HIGH:   prdata = high_en_q;
        IDX_INTR_LOW:    prdata = low_en_q;
        IDX_INTR_ENABLE: prdata = irq_en_q;
        IDX_INTR_STATUS: prdata = status_q;
        default:         prdata = 32'h0;
      endcase
    end
  end

  assign pready   = 1'b1;
  assign pslverr  = access & (~mapped | (pwrite & (idx == IDX_DATA_IN)));
  assign irq      = |(status_q & irq_en_q);
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];

endmodule
=== END FILE ===
