// Self-checking testbench for apb_gpio: N=8 and N=32 instances on one bus.
module apb_gpio_tb;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] gin;

  wire [31:0] prdata8, prdata32;
  wire        pready8, pready32, pslverr8, pslverr32;
  wire [7:0]  gout8, goe8;
  wire [31:0] gout32, goe32;
  wire        irq8, irq32;

  integer passed;
  integer failed;
  reg [8*64-1:0] nonce;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) u_n8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
    .gpio_in(gin[7:0]), .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) u_n32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
    .gpio_in(gin), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
  );

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  task chk32(input [31:0] got, input [31:0] exp);
    begin
      if (got !== exp) begin
        failed = failed + 1;
        $error("check %0d failed at %0t: got %h, expected %h", passed + failed, $time, got, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  task chk1(input got, input exp);
    begin
      if (got !== exp) begin
        failed = failed + 1;
        $error("check %0d failed at %0t: got %b, expected %b", passed + failed, $time, got, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  task chk_bus_quiet;
    begin
      chk32(prdata8, 32'h0);
      chk32(prdata32, 32'h0);
      chk1(pslverr8, 1'b0);
      chk1(pslverr32, 1'b0);
    end
  endtask

  task chk_pins(input [31:0] eo, input [31:0] ee);
    begin
      chk32(gout32, eo);
      chk32({24'h0, gout8}, eo & 32'h0000_00FF);
      chk32(goe32, ee);
      chk32({24'h0, goe8}, ee & 32'h0000_00FF);
    end
  endtask

  task chk_irq(input e32, input e8);
    begin
      chk1(irq32, e32);
      chk1(irq8, e8);
    end
  endtask

  task setup_phase(input [7:0] a, input w, input [31:0] d, input [3:0] s);
    begin
      @(negedge pclk);
      psel = 1'b1; penable = 1'b0; paddr = a; pwrite = w; pwdata = d; pstrb = s;
      #1;
      chk_bus_quiet;
    end
  endtask

  task access_phase(input [31:0] exp, input err);
    begin
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready8, 1'b1);
      chk1(pready32, 1'b1);
      chk1(pslverr8, err);
      chk1(pslverr32, err);
      chk32(prdata32, exp);
      chk32(prdata8, exp & 32'h0000_00FF);
    end
  endtask

  task wr(input [7:0] a, input [31:0] d, input [3:0] s, input err);
    begin
      setup_phase(a, 1'b1, d, s);
      access_phase(32'h0, err);
    end
  endtask

  task rd(input [7:0] a, input [31:0] exp, input err);
    begin
      setup_phase(a, 1'b0, 32'h0, 4'h0);
      access_phase(exp, err);
    end
  endtask

  task idle_cycles(input integer n);
    integer k;
    begin
      for (k = 0; k < n; k = k + 1) begin
        @(negedge pclk);
        psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
        paddr = 8'h00; pwdata = 32'h0;
        #1;
        chk_bus_quiet;
      end
    end
  endtask

  task rw_reg(input [7:0] a);
    begin
      wr(a, 32'hDEAD_BEEF, 4'b1001, 1'b0);
      rd(a, 32'hDE00_00EF, 1'b0);
      wr(a, 32'h0, 4'hF, 1'b0);
      rd(a, 32'h0, 1'b0);
    end
  endtask

  task read_all_zero;
    begin
      rd(8'h00, 32'h0, 1'b0);
      rd(8'h04, 32'h0, 1'b0);
      rd(8'h08, 32'h0, 1'b0);
      rd(8'h0C, 32'h0, 1'b0);
      rd(8'h10, 32'h0, 1'b0);
      rd(8'h14, 32'h0, 1'b0);
      rd(8'h18, 32'h0, 1'b0);
      rd(8'h1C, 32'h0, 1'b0);
      rd(8'h20, 32'h0, 1'b0);
    end
  endtask

  initial begin
    passed = 0;
    failed = 0;
    nonce = {(8*64){1'b0}};
    presetn = 1'b0;
    psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
    paddr = 8'h00; pwdata = 32'h0; pstrb = 4'h0;
    gin = 32'h0;

    // ---------------- reset values
    repeat (3) @(negedge pclk);
    chk_pins(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);
    presetn = 1'b1;
    read_all_zero;
    chk_pins(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);
    idle_cycles(1);

    // ---------------- DATA_OUT, strobes, back-to-back
    wr(8'h00, 32'hA5A5_5AF0, 4'hF, 1'b0);
    rd(8'h00, 32'hA5A5_5AF0, 1'b0);
    chk_pins(32'hA5A5_5AF0, 32'h0);
    wr(8'h00, 32'h1234_5678, 4'b0101, 1'b0);
    rd(8'h00, 32'hA534_5A78, 1'b0);
    wr(8'h00, 32'hFFFF_FFFF, 4'b0000, 1'b0);
    rd(8'h00, 32'hA534_5A78, 1'b0);
    chk_pins(32'hA534_5A78, 32'h0);
    idle_cycles(1);

    // ---------------- DIR
    wr(8'h04, 32'hFFFF_FFFF, 4'hF, 1'b0);
    rd(8'h04, 32'hFFFF_FFFF, 1'b0);
    wr(8'h04, 32'h0, 4'b0010, 1'b0);
    rd(8'h04, 32'hFFFF_00FF, 1'b0);
    chk_pins(32'hA534_5A78, 32'hFFFF_00FF);
    wr(8'h04, 32'h0, 4'b0001, 1'b0);
    rd(8'h04, 32'hFFFF_0000, 1'b0);
    chk_pins(32'hA534_5A78, 32'hFFFF_0000);
    idle_cycles(1);

    // ---------------- detection enables and interrupt enable (gin = 0)
    rw_reg(8'h0C);
    rw_reg(8'h10);
    rw_reg(8'h14);
    rw_reg(8'h1C);
    rd(8'h20, 32'h0, 1'b0);
    chk_irq(1'b0, 1'b0);
    idle_cycles(1);

    // ---------------- DATA_IN, read only
    gin = 32'hC3C3_1E2D;
    rd(8'h08, 32'hC3C3_1E2D, 1'b0);
    wr(8'h08, 32'hFFFF_FFFF, 4'hF, 1'b1);
    rd(8'h08, 32'hC3C3_1E2D, 1'b0);

    // ---------------- PSLVERR policy and decode aliasing
    rd(8'h24, 32'h0, 1'b1);
    rd(8'h01, 32'h0, 1'b1);
    rd(8'h02, 32'h0, 1'b1);
    rd(8'h03, 32'h0, 1'b1);
    rd(8'h3C, 32'h0, 1'b1);
    rd(8'h40, 32'h0, 1'b1);
    rd(8'h80, 32'h0, 1'b1);
    rd(8'hFC, 32'h0, 1'b1);
    wr(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
    rd(8'h00, 32'hA534_5A78, 1'b0);
    wr(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
    rd(8'h00, 32'hA534_5A78, 1'b0);
    wr(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
    rd(8'h04, 32'hFFFF_0000, 1'b0);
    wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
    wr(8'h5C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    rd(8'h1C, 32'h0, 1'b0);
    chk_pins(32'hA534_5A78, 32'hFFFF_0000);
    idle_cycles(1);
    gin = 32'h0;
    idle_cycles(3);

    // ---------------- rising edge: fires once, sticky, selective W1C
    wr(8'h0C, 32'h0001_0003, 4'hF, 1'b0);
    idle_cycles(1);
    gin = 32'h0001_0001;
    idle_cycles(2);
    chk_irq(1'b0, 1'b0);
    rd(8'h20, 32'h0001_0001, 1'b0);
    idle_cycles(3);
    rd(8'h20, 32'h0001_0001, 1'b0);
    wr(8'h20, 32'h0000_0001, 4'hF, 1'b0);
    rd(8'h20, 32'h0001_0000, 1'b0);
    wr(8'h20, 32'h0001_0000, 4'b1011, 1'b0);
    rd(8'h20, 32'h0001_0000, 1'b0);
    wr(8'h20, 32'h0, 4'hF, 1'b0);
    rd(8'h20, 32'h0001_0000, 1'b0);
    wr(8'h20, 32'h0001_0000, 4'b0100, 1'b0);
    rd(8'h20, 32'h0, 1'b0);
    idle_cycles(1);

    // ---------------- interrupt mask
    gin = 32'h0001_0003;
    idle_cycles(2);
    rd(8'h20, 32'h0000_0002, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr(8'h1C, 32'h0000_0020, 4'h1, 1'b0);
    idle_cycles(1);
    chk_irq(1'b0, 1'b0);
    wr(8'h1C, 32'h0000_0022, 4'h1, 1'b0);
    idle_cycles(1);
    chk_irq(1'b1, 1'b1);
    rd(8'h1C, 32'h0000_0022, 1'b0);
    wr(8'h20, 32'h0000_0002, 4'hF, 1'b0);
    idle_cycles(1);
    chk_irq(1'b0, 1'b0);
    rd(8'h20, 32'h0, 1'b0);

    // ---------------- falling edge on a pin above 8 (N=32 only) and irq
    wr(8'h10, 32'h0001_0000, 4'hF, 1'b0);
    idle_cycles(1);
    gin = 32'h0000_0003;
    idle_cycles(2);
    rd(8'h20, 32'h0001_0000, 1'b0);
    wr(8'h1C, 32'h0001_0022, 4'hF, 1'b0);
    idle_cycles(1);
    chk_irq(1'b1, 1'b0);
    wr(8'h20, 32'h0001_0000, 4'hF, 1'b0);
    idle_cycles(1);
    chk_irq(1'b0, 1'b0);
    rd(8'h20, 32'h0, 1'b0);

    // ---------------- falling edge on pin 0
    wr(8'h10, 32'h0000_0001, 4'hF, 1'b0);
    idle_cycles(1);
    gin = 32'h0000_0002;
    idle_cycles(2);
    rd(8'h20, 32'h0000_0001, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr(8'h20, 32'h0000_0001, 4'hF, 1'b0);
    rd(8'h20, 32'h0, 1'b0);
    wr(8'h10, 32'h0, 4'hF, 1'b0);
    wr(8'h0C, 32'h0, 4'hF, 1'b0);
    idle_cycles(1);

    // ---------------- high level: sets again after a clear
    gin = 32'h8000_0002;
    idle_cycles(2);
    rd(8'h20, 32'h0, 1'b0);
    wr(8'h14, 32'h8000_0006, 4'hF, 1'b0);
    idle_cycles(2);
    rd(8'h20, 32'h8000_0002, 1'b0);
    chk_irq(1'b1, 1'b1);
    wr(8'h20, 32'h8000_0002, 4'hF, 1'b0);
    rd(8'h20, 32'h8000_0002, 1'b0);
    idle_cycles(1);
    gin = 32'h0;
    idle_cycles(2);
    wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    rd(8'h20, 32'h0, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr(8'h14, 32'h0, 4'hF, 1'b0);

    // ---------------- low level
    wr(8'h18, 32'h0000_0101, 4'hF, 1'b0);
    idle_cycles(2);
    rd(8'h20, 32'h0000_0101, 1'b0);
    chk_irq(1'b0, 1'b0);
    wr(8'h20, 32'h0000_0001, 4'hF, 1'b0);
    rd(8'h20, 32'h0000_0101, 1'b0);
    idle_cycles(1);
    gin = 32'h0000_0001;
    idle_cycles(2);
    wr(8'h20, 32'h0000_0101, 4'hF, 1'b0);
    rd(8'h20, 32'h0000_0100, 1'b0);
    wr(8'h18, 32'h0, 4'hF, 1'b0);
    wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    rd(8'h20, 32'h0, 1'b0);
    idle_cycles(1);

    // ---------------- one-cycle pulse on pin 4
    gin = 32'h0;
    idle_cycles(2);
    wr(8'h0C, 32'h0000_0010, 4'hF, 1'b0);
    idle_cycles(1);
    gin = 32'h0000_0010;
    idle_cycles(1);
    gin = 32'h0;
    idle_cycles(2);
    rd(8'h20, 32'h0000_0010, 1'b0);
    wr(8'h20, 32'h0000_0010, 4'hF, 1'b0);
    rd(8'h20, 32'h0, 1'b0);
    wr(8'h0C, 32'h0, 4'hF, 1'b0);
    idle_cycles(1);

    // ---------------- a detection beats a clear on the same edge
    wr(8'h0C, 32'h0000_0008, 4'hF, 1'b0);
    idle_cycles(1);
    gin = 32'h0000_0008;
    idle_cycles(2);
    rd(8'h20, 32'h0000_0008, 1'b0);
    idle_cycles(1);
    gin = 32'h0;
    idle_cycles(2);
    rd(8'h20, 32'h0000_0008, 1'b0);
    setup_phase(8'h20, 1'b1, 32'h0000_0008, 4'hF);
    gin = 32'h0000_0008;
    access_phase(32'h0, 1'b0);
    rd(8'h20, 32'h0000_0008, 1'b0);
    wr(8'h20, 32'h0000_0008, 4'hF, 1'b0);
    rd(8'h20, 32'h0, 1'b0);
    wr(8'h0C, 32'h0, 4'hF, 1'b0);
    idle_cycles(1);

    // ---------------- reset again
    wr(8'h00, 32'hFFFF_FFFF, 4'hF, 1'b0);
    wr(8'h04, 32'hFFFF_FFFF, 4'hF, 1'b0);
    wr(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b0);
    wr(8'h14, 32'hFFFF_FFFF, 4'hF, 1'b0);
    idle_cycles(1);
    gin = 32'hFFFF_FFFF;
    idle_cycles(3);
    chk_irq(1'b1, 1'b1);
    chk_pins(32'hFFFF_FFFF, 32'hFFFF_FFFF);
    presetn = 1'b0;
    gin = 32'h0;
    idle_cycles(2);
    chk_pins(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);
    presetn = 1'b1;
    read_all_zero;
    chk_pins(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);
    idle_cycles(2);

    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

